 let seed=112;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 function grain(color){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.fillRect(0,0,128,128);const d=ctx.getImageData(0,0,128,128);for(let i=0;i<d.data.length;i+=4){const n=(random()-.5)*12;for(let k=0;k<3;k++)d.data[i+k]+=n;}ctx.putImageData(d,0,0);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(8,8);t.colorSpace=THREE.SRGBColorSpace;ts.add(t);return t;}
